result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/bedops/models.py", "content": """"Two simple one-day-ahead forecasters for daily bed census.

Both operate walk-forward: when predicting day ``t`` they may only use
actual observations up to day ``t - 1``.
"""

from __future__ import annotations


def naive_seasonal_forecast(history: list[int]) -> int:
    """Seasonal naive: predict the value observed 7 days earlier."""
    if len(history) < 7:
        raise ValueError("need at least 7 days of history")
    return int(history[-7])


def seasonal_ma_forecast(history: list[int], weeks: int = 4) -> int:
    """Seasonal moving average: mean of the same weekday over the last
    ``weeks`` weeks, rounded to the nearest integer."""
    if len(history) < 7 * weeks:
        raise ValueError(f"need at least {7 * weeks} days of history")
    window = [history[-7 * k] for k in range(1, weeks + 1)]
    return int(round(sum(window) / len(window)))


def _walk_forward(
    train: list[int],
    test: list[int],
    forecaster,
) -> list[int]:
    """One-day-ahead walk-forward predictions over the test window.

    After each prediction the actual observation is appended to the
    history before forecasting the next day.
    """
    history = list(train)
    predictions: list[int] = []
    for actual in test:
        pred = forecaster(history)
        predictions.append(int(pred))
        history.append(actual)
    return predictions


def run_naive_seasonal(train: list[int], test: list[int]) -> list[int]:
    """Walk-forward predictions using the seasonal-naive forecaster."""
    return _walk_forward(train, test, naive_seasonal_forecast)


def run_seasonal_ma(train: list[int], test: list[int]) -> list[int]:
    """Walk-forward predictions using the 4-week seasonal moving average."""
    return _walk_forward(train, test, seasonal_ma_forecast)
